/* Independent educational notes; see references and clinical disclaimer. */
window.MED_SPECIALIST = {"asOf":"2026-10-31","notes":[{"id":"sp-001","category":"Cardiology","title":"Acute chest pain","pattern":"Distinguish ischemic pressure, pleuritic pain, aortic pain, and musculoskeletal causes while checking stability.","assessment":"Combine ECG, serial cardiac injury markers where indicated, examination and pretest risk; a single normal ECG does not exclude ACS.","approach":"Escalate possible ACS promptly and follow locally approved emergency pathways.","pitfall":"Anchoring on reflux or anxiety before ruling out dangerous causes.","redFlags":"Shock, new hypoxia, syncope, crushing or tearing pain, ongoing ischemic symptoms.","sources":["acs"],"level":"Clinical / specialist review"},{"id":"sp-002","category":"Cardiology","title":"Acute coronary syndrome","pattern":"Plaque rupture or erosion with coronary thrombosis may cause unstable angina or myocardial infarction.","assessment":"Interpret symptoms, ECG evolution and dynamic troponin in clinical context; consider other causes of elevated troponin.","approach":"Timely cardiology pathway, antithrombotic assessment, reperfusion eligibility and secondary prevention require specialists.","pitfall":"Troponin elevation is myocardial injury, not always type 1 myocardial infarction.","redFlags":"Persistent pain, instability, ventricular arrhythmia, cardiogenic shock.","sources":["acs"],"level":"Clinical / specialist review"},{"id":"sp-003","category":"Cardiology","title":"Atrial fibrillation","pattern":"Irregular atrial activation produces an irregular ventricular response and variable clinical symptoms.","assessment":"Confirm on ECG, assess reversible drivers, hemodynamic status, structural disease and stroke/bleeding risk.","approach":"Individualize rate/rhythm strategy and anticoagulation decisions using approved tools and guidelines.","pitfall":"A single pulse check cannot establish a rhythm diagnosis; bleeding risk alone is not an automatic exclusion of anticoagulation.","redFlags":"Collapse, acute heart failure, chest pain, severe hypotension.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-004","category":"Cardiology","title":"Decompensated heart failure","pattern":"Fluid congestion and reduced cardiac performance can cause dyspnea, edema and fatigue; preserved ejection fraction is possible.","assessment":"Examine volume status and perfusion; consider BNP/NT-proBNP, ECG, CXR and echocardiography with clinical context.","approach":"Escalate respiratory compromise, evaluate triggers, optimize guideline-directed care after stabilization.","pitfall":"Edema or a normal EF alone cannot determine presence or absence of heart failure.","redFlags":"Severe hypoxia, hypotension, altered mentation, pulmonary edema.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-005","category":"Cardiology","title":"Syncope and collapse","pattern":"Transient loss of consciousness has reflex, orthostatic, cardiac and neurologic mimics.","assessment":"Witness history, ECG, orthostatic vitals when safe, medication review and cardiac risk features determine evaluation.","approach":"Urgent assessment when high-risk features exist; use targeted rather than indiscriminate imaging.","pitfall":"Mislabeling seizure or dangerous arrhythmia as benign fainting.","redFlags":"Exertional syncope, family sudden death, abnormal ECG, new neurologic deficit.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-006","category":"Cardiology","title":"Hypertension assessment","pattern":"Sustained blood pressure elevation is linked to vascular, cardiac, renal and cerebrovascular risk.","assessment":"Validate cuff and measurement technique, consider ambulatory/home monitoring and target-organ assessment.","approach":"Lifestyle advice, comorbidity assessment and medication choices depend on local guideline and patient factors.","pitfall":"Treating one anxious office reading as established sustained hypertension.","redFlags":"Severe BP with acute chest pain, neurologic deficits, pulmonary edema or encephalopathy.","sources":["hypertension"],"level":"Clinical / specialist review"},{"id":"sp-007","category":"Cardiology","title":"Valvular murmurs","pattern":"Flow turbulence may reflect stenosis, regurgitation, high-output states or innocent murmurs.","assessment":"Characterize timing, radiation, maneuvers, symptoms; echocardiography defines anatomy and severity.","approach":"Investigate symptoms and structural disease; severe symptomatic lesions need timely specialist review.","pitfall":"Murmur loudness does not reliably equal lesion severity.","redFlags":"Syncope with exertion, new pulmonary edema, acute severe regurgitation.","sources":["physical"],"level":"Clinical / specialist review"},{"id":"sp-008","category":"Respiratory","title":"Acute breathlessness","pattern":"Hypoxemia, hypercapnia, circulatory impairment and respiratory muscle fatigue have different mechanisms.","assessment":"Use ABCDE, pulse oximetry limits, work of breathing, targeted blood gas, ECG and imaging.","approach":"Treat deterioration as a time-critical emergency and seek cause-specific assessment.","pitfall":"Normal SpO2 does not exclude ventilation failure or impending fatigue.","redFlags":"Cyanosis, silent chest, altered consciousness, exhaustion, stridor.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-009","category":"Respiratory","title":"Asthma diagnosis and control","pattern":"Variable airflow limitation with airway inflammation produces episodic wheeze, cough or breathlessness.","assessment":"Seek objective variable airflow limitation using appropriate tests, review symptoms and triggers.","approach":"Review inhaler technique, adherence, exacerbation risk and ICS-containing treatment strategies per current GINA.","pitfall":"Relying only on symptoms or SABA-only maintenance strategy.","redFlags":"Inability to speak, drowsiness, quiet chest, worsening fatigue.","sources":["asthma"],"level":"Clinical / specialist review"},{"id":"sp-010","category":"Respiratory","title":"COPD assessment","pattern":"Persistent airflow obstruction is often related to exposure history and airway or parenchymal injury.","assessment":"Post-bronchodilator spirometry confirms airflow obstruction in the appropriate clinical context.","approach":"Assess symptoms, exacerbations, smoking cessation, vaccinations, comorbidities and pulmonary rehabilitation.","pitfall":"Do not diagnose COPD from symptoms or chest imaging alone.","redFlags":"Acute severe dyspnea, confusion, hypercapnic respiratory failure.","sources":["copd"],"level":"Clinical / specialist review"},{"id":"sp-011","category":"Respiratory","title":"Pulmonary embolism","pattern":"Venous thromboembolism in pulmonary vessels can impair oxygenation and right ventricular function.","assessment":"Use validated clinical probability first; D-dimer and imaging depend on risk, not isolated nonspecific symptoms.","approach":"Urgent escalation for suspected high-risk PE; assessment of anticoagulation suitability is individualized.","pitfall":"A negative D-dimer is not a universal rule-out in high pretest probability.","redFlags":"Shock, syncope, worsening hypoxia, right heart strain.","sources":["vte"],"level":"Clinical / specialist review"},{"id":"sp-012","category":"Respiratory","title":"Pneumothorax","pattern":"Air in the pleural space may cause sudden pleuritic pain and reduced breath sounds.","assessment":"Evaluate hemodynamic status first; consider ultrasound or radiography when stable.","approach":"Suspected tension physiology is a clinical emergency needing immediate trained intervention.","pitfall":"Waiting for imaging in an unstable patient with convincing tension physiology.","redFlags":"Hypotension, severe respiratory distress, rapidly worsening hypoxia.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-013","category":"Respiratory","title":"Pneumonia","pattern":"Parenchymal infection produces respiratory and systemic inflammatory symptoms, with diverse causes.","assessment":"Use severity and oxygenation assessment, chest imaging when indicated and clinical diagnosis.","approach":"Antimicrobial decisions should follow severity, local guidance, allergies and stewardship principles.","pitfall":"A normal early radiograph or absence of fever does not exclude pneumonia.","redFlags":"New confusion, shock, hypoxia, inability to maintain intake.","sources":["steward"],"level":"Clinical / specialist review"},{"id":"sp-014","category":"Respiratory","title":"Pleural effusion","pattern":"Fluid accumulates in pleural space from cardiac, infectious, malignant or inflammatory causes.","assessment":"History and ultrasound help localize; selected patients require diagnostic pleural fluid analysis.","approach":"Investigate underlying cause; procedural sampling needs consent, ultrasound and trained operators.","pitfall":"Not every effusion is due to heart failure or safely tapped without imaging.","redFlags":"Fever with large effusion, severe dyspnea, marked instability.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-015","category":"Nephrology","title":"Acute kidney injury","pattern":"Abrupt deterioration in filtration can arise from prerenal hypoperfusion, intrinsic injury or obstruction.","assessment":"Review creatinine trend, urine output, volume status, medications and possible obstruction.","approach":"Escalate life-threatening electrolyte, acid-base or fluid problems and address reversible triggers.","pitfall":"A seemingly modest creatinine change may be clinically important in low-muscle-mass patients.","redFlags":"Hyperkalemic ECG changes, pulmonary edema, anuria, encephalopathy.","sources":["aki"],"level":"Clinical / specialist review"},{"id":"sp-016","category":"Nephrology","title":"Chronic kidney disease staging","pattern":"CKD classification combines kidney filtration and evidence of damage over time.","assessment":"Use eGFR with urinary albumin-to-creatinine ratio, chronicity and clinical history.","approach":"Assess cardiovascular risk, progression factors, medicine dosing and nephrology referral indications.","pitfall":"Single abnormal eGFR value cannot by itself prove CKD.","redFlags":"Progressive rapid decline, refractory electrolyte derangement, severe uremic features.","sources":["ckd"],"level":"Clinical / specialist review"},{"id":"sp-017","category":"Nephrology","title":"Hyperkalemia reasoning","pattern":"Potassium excess can impair membrane excitability and cause dangerous conduction changes.","assessment":"Repeat unexpected results, review hemolysis, renal function, drugs and ECG; ECG can be normal in severe hyperkalemia.","approach":"Suspected severe hyperkalemia warrants immediate monitored clinical assessment under local emergency protocol.","pitfall":"Assuming a normal ECG excludes dangerous hyperkalemia.","redFlags":"Weakness, arrhythmia, syncope, cardiac arrest.","sources":["aki"],"level":"Clinical / specialist review"},{"id":"sp-018","category":"Nephrology","title":"Hyponatremia framework","pattern":"Low plasma sodium reflects water balance rather than simply sodium depletion.","assessment":"Determine tonicity, symptom burden, time course, volume context and relevant medications.","approach":"Correction planning must account for risk of osmotic demyelination and specialist monitoring.","pitfall":"Overly rapid correction risks serious neurologic injury; use no generic rate without context.","redFlags":"Seizures, coma, severe confusion.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-019","category":"Nephrology","title":"Acid-base interpretation","pattern":"Primary metabolic or respiratory processes may coexist with compensation and mixed disorders.","assessment":"Read pH, PaCO2, bicarbonate, anion gap and clinical context in sequence.","approach":"Treat underlying cause; blood gas numbers alone are not a treatment target.","pitfall":"Assuming any near-normal pH means a normal acid-base state.","redFlags":"Severe respiratory exhaustion, shock, toxic ingestion, severe acidosis.","sources":["lab"],"level":"Clinical / specialist review"},{"id":"sp-020","category":"Endocrinology","title":"Diabetic ketoacidosis","pattern":"Insulin deficiency with ketogenesis and acidosis can occur with hyperglycemia or euglycemia.","assessment":"Check ketones, anion gap, blood gas, electrolytes, glucose and precipitating cause.","approach":"Emergency fluid, electrolyte and insulin pathways require continuous monitoring and trained care.","pitfall":"Normal or mildly high glucose does not rule out DKA, particularly with SGLT2 exposure.","redFlags":"Altered consciousness, shock, severe dehydration, deep breathing.","sources":["diabetes"],"level":"Clinical / specialist review"},{"id":"sp-021","category":"Endocrinology","title":"Hyperosmolar hyperglycemic state","pattern":"Profound hyperosmolarity and dehydration may produce neurologic changes, often with less ketonemia.","assessment":"Evaluate osmolality, electrolytes, volume deficit, cognition and mixed DKA/HHS features.","approach":"Critical fluid and metabolic management depends on careful monitored protocols.","pitfall":"Rapid shifts in osmolality or sodium can cause harm.","redFlags":"Seizures, coma, shock, profound dehydration.","sources":["diabetes"],"level":"Clinical / specialist review"},{"id":"sp-022","category":"Endocrinology","title":"Hypoglycemia","pattern":"Low blood glucose causes autonomic and neuroglycopenic symptoms; risk rises with insulin and some secretagogues.","assessment":"Verify capillary or plasma glucose promptly where possible; evaluate drug exposure and nutritional status.","approach":"Management depends on consciousness and airway protection; investigate recurrence risk.","pitfall":"Do not give oral intake to someone unable to swallow safely.","redFlags":"Seizure, unconsciousness, inability to swallow.","sources":["diabetes"],"level":"Clinical / specialist review"},{"id":"sp-023","category":"Endocrinology","title":"Thyroid dysfunction","pattern":"Thyroid hormone excess or deficiency affects metabolic rate, cardiovascular and neurologic function.","assessment":"Interpret TSH and free thyroid hormones with illness, medications and pregnancy context.","approach":"Review symptoms, etiology and complications before treatment decisions.","pitfall":"Critical illness and certain medicines alter assays without primary thyroid disease.","redFlags":"High fever with marked tachycardia or hypothermia with reduced consciousness.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-024","category":"Endocrinology","title":"Adrenal insufficiency","pattern":"Glucocorticoid deficiency may manifest as fatigue, hypotension, electrolyte disturbance or collapse.","assessment":"Consider steroid exposure, adrenal disease, glucose, sodium and cortisol testing context.","approach":"Suspected adrenal crisis requires emergency senior-led management; diagnostic sampling must not delay lifesaving care.","pitfall":"Stopping chronic steroids abruptly may precipitate crisis.","redFlags":"Shock, vomiting with collapse, severe hypotension.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-025","category":"Neurology","title":"Acute stroke and TIA","pattern":"Focal neurologic dysfunction can reflect ischemia or hemorrhage; symptom resolution does not remove urgency.","assessment":"Establish last-known-well time, glucose, neurological findings and rapid specialist imaging pathway.","approach":"Time-critical stroke-team review and appropriate imaging determine therapy eligibility.","pitfall":"Do not wait for deficits to worsen or assume brief symptoms are harmless.","redFlags":"Sudden focal weakness, aphasia, vision loss, severe new neurological signs.","sources":["neuro"],"level":"Clinical / specialist review"},{"id":"sp-026","category":"Neurology","title":"New severe headache","pattern":"Most headaches are benign but thunderclap onset and systemic signs suggest dangerous causes.","assessment":"Characterize onset, meningism, neuro deficit, pregnancy, trauma and immunosuppression.","approach":"Emergency investigation when red flags indicate hemorrhage, infection or raised intracranial pressure.","pitfall":"A normal neurologic examination does not exclude subarachnoid hemorrhage.","redFlags":"Thunderclap onset, new focal deficit, fever with neck stiffness.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-027","category":"Neurology","title":"First seizure","pattern":"A convulsive episode may arise from epilepsy, metabolic disturbances, intoxication or syncope mimics.","assessment":"Witness description, glucose/electrolytes, context, ECG and appropriate neurologic evaluation matter.","approach":"Protect airway and prevent injury; refer prolonged or recurrent seizure activity urgently.","pitfall":"A witnessed shaking episode is not automatically epilepsy.","redFlags":"Prolonged seizure, repeated seizures without recovery, pregnancy, major trauma.","sources":["epilepsy"],"level":"Clinical / specialist review"},{"id":"sp-028","category":"Neurology","title":"Delirium","pattern":"Acute fluctuating attention and cognition usually signal an underlying medical problem.","assessment":"Document baseline, medicines, infection, metabolic changes, pain, withdrawal and sensory impairment.","approach":"Treat urgent drivers, provide orientation and non-pharmacologic support, and protect safety.","pitfall":"A quiet hypoactive delirium can be missed or mistaken for dementia.","redFlags":"Abrupt deterioration, low oxygenation, severe withdrawal or sepsis signs.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-029","category":"Neurology","title":"Peripheral neuropathy","pattern":"Length-dependent sensory or motor changes may stem from diabetes, toxins, deficiencies or inflammation.","assessment":"Pattern localization, reflexes, autonomic symptoms and targeted nerve/lab studies guide evaluation.","approach":"Address underlying causes and safety; rapid progressive weakness needs urgent specialist review.","pitfall":"Not all tingling comes from peripheral neuropathy; cord disease may mimic it.","redFlags":"Rapid ascending weakness, respiratory weakness, new sphincter disturbance.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-030","category":"Gastroenterology","title":"Upper gastrointestinal bleeding","pattern":"Hematemesis or melena reflects bleeding proximal to ligament of Treitz, with variceal and nonvariceal causes.","assessment":"Assess shock physiology, CBC trend, anticoagulants and liver disease; endoscopy after stabilization.","approach":"Early senior review, blood-product safety and risk stratification follow emergency guidelines.","pitfall":"Initial hemoglobin may not yet reflect acute blood loss.","redFlags":"Syncope, hemodynamic instability, active hematemesis.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-031","category":"Gastroenterology","title":"Acute abdominal pain","pattern":"Location and physiology suggest surgical, inflammatory, vascular, metabolic or gynecologic causes.","assessment":"Characterize onset, peritonism, pregnancy possibility and bedside instability; target imaging appropriately.","approach":"Early surgical or emergency consultation for concerning features.","pitfall":"Analgesia should not be withheld just to preserve examination findings.","redFlags":"Rigid abdomen, shock, severe sudden pain, GI bleeding.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-032","category":"Gastroenterology","title":"Jaundice approach","pattern":"Unconjugated, hepatocellular and cholestatic patterns suggest different mechanisms.","assessment":"Look at bilirubin fractions, ALT/AST, ALP/GGT, hemolysis indicators and ultrasound findings.","approach":"Review hepatotoxic medicines, obstruction and viral risk; urgent assessment if cholangitis suspected.","pitfall":"A single liver enzyme level is not a measure of overall liver function.","redFlags":"Fever with jaundice and hypotension, encephalopathy, bleeding.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-033","category":"Gastroenterology","title":"Cirrhosis complications","pattern":"Portal hypertension and impaired synthetic function drive varices, ascites and encephalopathy.","assessment":"Evaluate infection, renal injury, GI bleeding, fluid changes and precipitating drugs.","approach":"Coordinate surveillance, nutrition, etiology management and escalation for decompensation.","pitfall":"Altered behavior in cirrhosis is not always hepatic encephalopathy; rule out other causes.","redFlags":"GI bleeding, fever with ascites, worsening confusion or renal failure.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-034","category":"Gastroenterology","title":"Acute pancreatitis","pattern":"Pancreatic inflammation commonly relates to gallstones or alcohol but has multiple etiologies.","assessment":"Correlate characteristic pain with lipase and imaging when clinically needed; assess severity and organ dysfunction.","approach":"Supportive management and gallstone evaluation depend on context and severity.","pitfall":"Lipase elevation alone does not diagnose pancreatitis in every setting.","redFlags":"Shock, organ failure, hypoxia, worsening abdominal findings.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-035","category":"Hematology","title":"Microcytic anemia","pattern":"Iron deficiency, thalassemia, chronic inflammation and other mechanisms can produce small red cells.","assessment":"Review MCV, ferritin with inflammation, smear, reticulocyte response and blood-loss risk.","approach":"Treat cause, not simply hemoglobin number; consider GI blood-loss investigation where appropriate.","pitfall":"Ferritin can rise with inflammation and mask iron deficiency.","redFlags":"Syncope, chest pain, active bleeding, profound symptoms.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-036","category":"Hematology","title":"Macrocytosis and B12 deficiency","pattern":"Large red cells can result from B12/folate issues, liver disease, hypothyroidism or marrow pathology.","assessment":"Check reticulocytes, smear, B12-related assessment and medication or alcohol history.","approach":"Neurologic B12 symptoms warrant timely recognition; investigate cause before assuming dietary deficiency.","pitfall":"Folate alone can obscure anemia while neurologic B12 damage progresses.","redFlags":"Rapid neurologic deterioration, severe symptomatic anemia.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-037","category":"Hematology","title":"Thrombocytopenia","pattern":"Low platelets arise from reduced production, immune destruction, consumption, dilution or sequestration.","assessment":"Confirm genuine result, inspect smear and bleeding signs, evaluate drugs and systemic illness.","approach":"Urgent hematology escalation when microangiopathy, major bleeding or very low platelets suspected.","pitfall":"EDTA-related clumping can mimic thrombocytopenia.","redFlags":"Bleeding with confusion, renal injury, hemolysis or shock.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-038","category":"Hematology","title":"Neutropenic fever","pattern":"Fever in severe neutropenia can indicate life-threatening infection despite subtle local signs.","assessment":"Evaluate treatment history, neutrophil count, cultures when safe and sepsis physiology.","approach":"Immediate specialist assessment and institution-specific antimicrobial pathway is critical.","pitfall":"Do not wait for localized signs before escalating potentially serious infection.","redFlags":"Fever, chills, hypotension or confusion with neutropenia.","sources":["steward"],"level":"Clinical / specialist review"},{"id":"sp-039","category":"Infectious Disease","title":"Sepsis recognition","pattern":"Infection with life-threatening organ dysfunction can evolve without dramatic fever.","assessment":"Use suspected infection plus structured physiology such as NEWS2 where applicable and look for perfusion abnormalities.","approach":"Actively reassess, escalate promptly and use the current NICE/SSC/local pathway.","pitfall":"Do not use one biomarker alone to establish or exclude sepsis.","redFlags":"New confusion, mottled skin, severe respiratory compromise, hypotension.","sources":["sepsis"],"level":"Clinical / specialist review"},{"id":"sp-040","category":"Infectious Disease","title":"Antimicrobial stewardship","pattern":"Appropriate antibiotics depend on syndrome, organism likelihood, resistance and patient-specific risks.","assessment":"Confirm a working diagnosis; review source control, microbiology, renal function, allergies and local antibiogram.","approach":"Document indication and review date; narrow or stop treatment when clinically supported.","pitfall":"Broad-spectrum therapy without review can cause resistance and harm.","redFlags":"Deterioration with infection despite therapy, severe adverse drug reaction.","sources":["steward"],"level":"Clinical / specialist review"},{"id":"sp-041","category":"Infectious Disease","title":"Tuberculosis evaluation","pattern":"Persistent cough and systemic illness require risk-sensitive TB consideration, especially in high-burden settings.","assessment":"Assess exposure, weight loss, radiology and WHO-recommended molecular testing and resistance detection.","approach":"Apply infection prevention and national TB program diagnostic/treatment pathways.","pitfall":"Single negative sample does not always exclude TB in high suspicion.","redFlags":"Hemoptysis, respiratory failure, disseminated disease or severe immunosuppression.","sources":["tb"],"level":"Clinical / specialist review"},{"id":"sp-042","category":"Infectious Disease","title":"Meningitis red flags","pattern":"Meningeal infection can present with fever, headache, altered mental state or rash, sometimes incompletely.","assessment":"Assess ABCDE, focal deficits, seizures and whether imaging/LP are appropriate after urgent stabilization.","approach":"Immediate emergency referral; treatment timing must follow an approved specialist pathway.","pitfall":"Do not delay urgent care waiting for a classic triad to appear.","redFlags":"Rapid decline, purpuric rash, seizure, altered consciousness.","sources":["meningitis"],"level":"Clinical / specialist review"},{"id":"sp-043","category":"Infectious Disease","title":"Isolation and standard precautions","pattern":"Core hand hygiene and risk-adapted PPE reduce avoidable healthcare-associated infection.","assessment":"Use exposure route, suspected pathogen and local infection prevention guidance.","approach":"Apply standard precautions to every patient; add transmission-based precautions as indicated.","pitfall":"Gloves do not replace hand hygiene.","redFlags":"High-risk exposure incidents, suspected airborne infection without protection.","sources":["cdc"],"level":"Clinical / specialist review"},{"id":"sp-044","category":"Rheumatology","title":"Inflammatory versus mechanical arthritis","pattern":"Morning stiffness, synovitis and systemic features may distinguish inflammation from wear-related pain.","assessment":"Examine joint swelling, distribution, inflammatory markers and targeted autoantibodies when warranted.","approach":"Early referral for persistent inflammatory synovitis can preserve function.","pitfall":"A negative rheumatoid factor does not exclude inflammatory arthritis.","redFlags":"Hot swollen joint with fever or systemic illness.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-045","category":"Rheumatology","title":"Septic arthritis","pattern":"Joint infection may rapidly damage cartilage and cause systemic infection.","assessment":"Recognize acutely painful reduced-range joint; synovial aspiration by trained clinicians is central when indicated.","approach":"Urgent orthopedics/infectious disease review and source-focused management.","pitfall":"Normal serum white count does not safely exclude septic arthritis.","redFlags":"Fever, intense pain, inability to move joint, systemic toxicity.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-046","category":"Rheumatology","title":"Giant cell arteritis","pattern":"Large-vessel inflammation may produce temporal pain, jaw claudication and visual symptoms in older adults.","assessment":"Consider headache pattern, scalp tenderness, visual findings and inflammatory tests within urgent pathway.","approach":"Visual symptoms require immediate specialist assessment; treatment is time-sensitive.","pitfall":"Normal or mildly elevated inflammation markers do not always rule it out.","redFlags":"Transient or persistent visual loss.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-047","category":"Obstetrics","title":"Ectopic pregnancy","pattern":"Pregnancy implanted outside the uterine cavity can cause bleeding and rupture.","assessment":"In reproductive-age abdominal pain, consider pregnancy test and ultrasound based on timing and stability.","approach":"Hemodynamic instability requires urgent obstetric/gynecologic care.","pitfall":"A reassuring early ultrasound may not locate a very early pregnancy.","redFlags":"Syncope, shoulder-tip pain, peritonism, shock.","sources":["ob"],"level":"Clinical / specialist review"},{"id":"sp-048","category":"Obstetrics","title":"Pre-eclampsia recognition","pattern":"Hypertensive pregnancy disorder can involve end-organ dysfunction and placental complications.","assessment":"Check BP technique, urine protein and indicated maternal labs and fetal assessment.","approach":"Urgent maternity referral where severe features suspected; decision-making requires gestational context.","pitfall":"Proteinuria is not the only possible marker of severe disease.","redFlags":"Severe headache, visual disturbance, right upper quadrant pain, seizures.","sources":["ob"],"level":"Clinical / specialist review"},{"id":"sp-049","category":"Obstetrics","title":"Postpartum hemorrhage","pattern":"Postpartum bleeding can arise from uterine atony, trauma, retained tissue or coagulopathy.","assessment":"Rapidly assess blood loss and hemodynamics, obstetric factors and resuscitation needs.","approach":"Activate obstetric hemorrhage team and institution protocol immediately.","pitfall":"Visual blood-loss estimates often underestimate severity.","redFlags":"Ongoing heavy bleeding, shock or declining consciousness.","sources":["ob"],"level":"Clinical / specialist review"},{"id":"sp-050","category":"Obstetrics","title":"Maternal sepsis","pattern":"Infection can progress rapidly during pregnancy and post partum; normal physiologic baselines differ.","assessment":"Use pregnancy-adapted clinical assessment and relevant maternity guidance.","approach":"Escalate immediately to obstetrics and critical care as indicated.","pitfall":"Do not apply non-pregnant adult sepsis rule sets indiscriminately.","redFlags":"Altered consciousness, shock, severe dyspnea, rapidly deteriorating postpartum patient.","sources":["ob"],"level":"Clinical / specialist review"},{"id":"sp-051","category":"Pediatrics","title":"Febrile child assessment","pattern":"Age, immunization, activity, perfusion and hydration alter fever risk assessment.","assessment":"Combine clinical appearance, vital signs and focused examination; infant thresholds differ markedly.","approach":"Early pediatric assessment for high-risk age or findings.","pitfall":"Fever height by itself is an unreliable measure of serious illness.","redFlags":"Poor perfusion, reduced responsiveness, respiratory distress, non-blanching rash.","sources":["pediatric"],"level":"Clinical / specialist review"},{"id":"sp-052","category":"Pediatrics","title":"Pediatric dehydration","pattern":"Fluid loss changes perfusion and electrolytes; young children can deteriorate more quickly.","assessment":"Look at mental status, intake, urine output, capillary refill and mucosa in context.","approach":"Route and quantity of rehydration require weight-based clinical protocol.","pitfall":"Capillary refill alone is not definitive and can be affected by temperature.","redFlags":"Lethargy, shock, inability to retain fluids.","sources":["pediatric"],"level":"Clinical / specialist review"},{"id":"sp-053","category":"Pediatrics","title":"Pediatric respiratory distress","pattern":"Respiratory effort may be reflected in retractions, nasal flaring, grunting and feeding difficulty.","assessment":"Assess age-adjusted respiratory rate, air entry, oxygenation and fatigue.","approach":"Escalate to pediatric emergency teams for severe effort or exhaustion.","pitfall":"Transiently normal oxygen saturation can coexist with significant effort.","redFlags":"Apnea, exhaustion, poor consciousness, cyanosis.","sources":["pediatric"],"level":"Clinical / specialist review"},{"id":"sp-054","category":"Surgery","title":"Acute appendicitis","pattern":"Migration of pain to right lower quadrant and focal inflammatory signs are suggestive, not diagnostic.","assessment":"Combine examination with labs, pregnancy considerations and targeted imaging as appropriate.","approach":"Early surgical consultation for probable acute abdomen.","pitfall":"Absence of fever or high white count does not exclude appendicitis.","redFlags":"Generalized peritonitis, sepsis, hemodynamic instability.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-055","category":"Surgery","title":"Bowel obstruction","pattern":"Mechanical blockage or ileus can cause distension, vomiting and failure to pass stool/flatus.","assessment":"Prior surgery, hernia exam, hydration assessment and CT when indicated help define etiology.","approach":"Early surgical advice for obstruction with red flags.","pitfall":"Diarrhea or some stool passage may occur in partial obstruction.","redFlags":"Peritonitis, strangulation concern, severe persistent pain, shock.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-056","category":"Surgery","title":"Acute limb ischemia","pattern":"Sudden arterial flow loss threatens limb tissue.","assessment":"Assess onset, pulses, sensory-motor function, limb temperature and Doppler availability.","approach":"Immediate vascular referral; prompt assessment is limb-saving.","pitfall":"A palpable proximal pulse may not exclude distal ischemia.","redFlags":"Pain with pallor, paresthesia, paralysis or pulselessness.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-057","category":"Surgery","title":"Postoperative fever","pattern":"Early postoperative symptoms have infectious and noninfectious explanations.","assessment":"Assess timing, operative site, devices, respiratory status, urine and VTE risk.","approach":"Address high-risk systemic findings and discuss with surgical team.","pitfall":"Assuming all postoperative fevers are wound infections.","redFlags":"Shock, worsening abdominal pain, respiratory distress, altered mental status.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-058","category":"Oncology","title":"Unexplained weight loss and cancer alarms","pattern":"Persistent unexplained systemic change may reflect malignant, infectious, endocrine or psychiatric conditions.","assessment":"Take focused history for progressive symptoms, bleeding, lumps, personal risk and examine appropriately.","approach":"Use age- and symptom-specific suspected cancer referral criteria where applicable.","pitfall":"A normal basic laboratory panel does not eliminate concerning symptoms.","redFlags":"Progressive dysphagia, bleeding, new mass, marked decline.","sources":["cancer"],"level":"Clinical / specialist review"},{"id":"sp-059","category":"Oncology","title":"Cancer-associated infection","pattern":"Chemotherapy and immunosuppression can blunt conventional inflammatory responses.","assessment":"Check treatment timing, temperature, hemodynamics, neutrophils and access devices.","approach":"Treat suspected neutropenic sepsis as a time-critical pathway.","pitfall":"Do not assume no fever means no severe infection in immunocompromised patients.","redFlags":"Rigors, hypotension, confusion, breathlessness.","sources":["steward"],"level":"Clinical / specialist review"},{"id":"sp-060","category":"Psychiatry","title":"Suicide and self-harm assessment","pattern":"Acute distress, previous attempts, access to means and dynamic factors require direct, compassionate assessment.","assessment":"Assess current ideation, intent, plan, protective factors, substances, psychosis and supports.","approach":"Urgent mental-health and safeguarding escalation according to risk and local pathways.","pitfall":"A numerical risk score cannot substitute for a collaborative clinical formulation.","redFlags":"Current intent with access to means, inability to maintain immediate safety.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-061","category":"Psychiatry","title":"Delirium versus dementia","pattern":"Delirium is typically acute and fluctuating; dementia usually progresses chronically, though coexistence is common.","assessment":"Compare baseline cognition, attention, onset and medical drivers.","approach":"Investigate acute changes medically before labeling a chronic psychiatric diagnosis.","pitfall":"Hallucinations or agitation do not necessarily mean primary psychosis.","redFlags":"Rapid fluctuating confusion, fever, hypoxia, shock.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-062","category":"Dermatology","title":"Drug eruption recognition","pattern":"Drug-associated rashes range from benign exanthems to life-threatening mucocutaneous reactions.","assessment":"Assess timing, distribution, fever, mucosal involvement and newly started agents.","approach":"Stop and urgently escalate suspected severe cutaneous adverse reactions via licensed care.","pitfall":"Treating painful mucosal blistering as a routine allergy.","redFlags":"Skin detachment, painful rash, mucosal erosions, systemic illness.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-063","category":"Dermatology","title":"Cellulitis versus mimics","pattern":"Red, swollen skin may be infectious, inflammatory or vascular.","assessment":"Look for warmth, tenderness, expansion, systemic findings and bilateral patterns.","approach":"Use local antibiotic guidance when true cellulitis is likely; evaluate alternatives.","pitfall":"Bilateral leg erythema without systemic illness often has noninfectious explanations.","redFlags":"Disproportionate pain, rapidly spreading lesion, crepitus, shock.","sources":["steward"],"level":"Clinical / specialist review"},{"id":"sp-064","category":"Geriatrics","title":"Falls in older adults","pattern":"Falls may follow gait problems, hypotension, medication effects, arrhythmia or acute illness.","assessment":"Review injury, cognition, orthostatic BP, mobility, medicines and environment.","approach":"Target reversible risks and coordinated rehabilitation planning.","pitfall":"Not all falls are mechanical; ask about presyncope and loss of consciousness.","redFlags":"Head injury on anticoagulation, new weakness, collapse.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-065","category":"Geriatrics","title":"Frailty and polypharmacy","pattern":"Multisystem vulnerability raises adverse treatment and hospitalization risk.","assessment":"Review function, goals, medicines, nutrition, cognition and carer support.","approach":"Use shared decisions and regular medicine reconciliation.","pitfall":"Deprescribing requires consideration of indication, withdrawal risk and clinical oversight.","redFlags":"New confusion, recurrent falls, inability to maintain essential intake.","sources":["who"],"level":"Clinical / specialist review"},{"id":"sp-066","category":"Ethics & Safety","title":"Consent and capacity","pattern":"Decision-specific capacity requires understanding, retention, weighing and communication, with legal variation.","assessment":"Ensure explanation, voluntariness, language support and document the discussion.","approach":"Follow governing laws and institutional policy; do not substitute family assent when patient has capacity.","pitfall":"Capacity is not equivalent to agreeing with the clinician.","redFlags":"Emergency treatment without clear consent pathway or suspected coercion.","sources":["ethics"],"level":"Clinical / specialist review"},{"id":"sp-067","category":"Ethics & Safety","title":"Structured handover","pattern":"Accurate handover communicates situation, background, assessment and action plan.","assessment":"Summarize instability, important results, tasks, contingencies and named responsibility.","approach":"Use read-back for critical tasks and escalation thresholds.","pitfall":"A copy-pasted note does not replace direct high-risk communication.","redFlags":"Unacknowledged critical result, deterioration between teams.","sources":["who"],"level":"Clinical / specialist review"},{"id":"sp-068","category":"Ethics & Safety","title":"Diagnostic time-out","pattern":"Cognitive errors include anchoring, premature closure and ignoring disconfirming data.","assessment":"Ask: What diagnosis would be most dangerous to miss? What does not fit? What would change my mind?","approach":"Document uncertainty and safety-netting rather than false certainty.","pitfall":"Overordering indiscriminate tests also produces harm.","redFlags":"Unresolved instability, unexpected worsening, incompatible results.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-069","category":"Critical Care","title":"ABCDE primary survey","pattern":"Prioritize reversible immediate threats before completing a history.","assessment":"Reassess airway, breathing, circulation, disability and exposure repeatedly.","approach":"Call for appropriately trained help, monitor and document trends.","pitfall":"Completing detailed tests while ignoring immediate deterioration.","redFlags":"Airway obstruction, shock, severe hypoxia, reduced consciousness.","sources":["aha"],"level":"Clinical / specialist review"},{"id":"sp-070","category":"Critical Care","title":"Cardiac arrest recognition","pattern":"Unresponsiveness with absent normal breathing is a resuscitation emergency.","assessment":"Follow local BLS/ALS and current AHA/ERC guidance with team roles and AED/defibrillator pathway.","approach":"Formal practical training and institutional algorithms are essential.","pitfall":"Agonal gasps are not normal breathing; do not delay emergency response.","redFlags":"Unresponsive patient without normal breathing.","sources":["aha"],"level":"Clinical / specialist review"},{"id":"sp-071","category":"Critical Care","title":"Shock differentiation","pattern":"Hypovolemic, distributive, cardiogenic and obstructive shock may overlap.","assessment":"Interpret perfusion, bedside ultrasound where trained, ECG, infection signs and volume context.","approach":"Urgent source-specific response and reassessment; undifferentiated fluids can be harmful in some states.","pitfall":"Normal BP does not rule out early shock.","redFlags":"Altered mentation, mottling, oliguria, rising lactate with clinical compromise.","sources":["ssc"],"level":"Clinical / specialist review"},{"id":"sp-072","category":"Critical Care","title":"Oxygen and ventilation safety","pattern":"Oxygenation and carbon dioxide clearance are different physiologic problems.","assessment":"Assess work of breathing, SpO2 signal quality, blood gas when relevant, airway risk.","approach":"Use condition-specific targets and expert escalation for impending failure.","pitfall":"Giving oxygen alone does not correct severe hypoventilation.","redFlags":"Exhaustion, altered consciousness, apnea, severe hypoxia.","sources":["msd"],"level":"Clinical / specialist review"},{"id":"sp-073","category":"Clinical Skills","title":"History of presenting complaint","pattern":"A clear chronology helps prioritize the most probable and the must-not-miss diagnoses.","assessment":"Ask onset, progression, associated symptoms, prior episodes, medication exposure and patient concerns.","approach":"Summarize key positives and negatives, then state an explicit differential.","pitfall":"Unfocused exhaustive questions may miss rapid deterioration.","redFlags":"Any unstable vital signs during interview.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-074","category":"Clinical Skills","title":"Cardiovascular examination","pattern":"Inspect, palpate and auscultate systematically, while integrating vitals and peripheral signs.","assessment":"Assess pulse rhythm, JVP, heart sounds, murmurs and edema; correlate with symptoms.","approach":"Follow abnormal findings with appropriate cardiovascular investigation.","pitfall":"Exam findings complement rather than replace echocardiography.","redFlags":"New severe breathlessness or syncope with suspected valve disease.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-075","category":"Clinical Skills","title":"Respiratory examination","pattern":"Work of breathing, chest expansion, percussion and auscultation offer pattern clues.","assessment":"Compare bilaterally, consider wheeze, crackles and asymmetry with oxygenation.","approach":"Escalate severe effort; investigations guided by presentation.","pitfall":"Chest sounds have variable accuracy; do not rely on one isolated sign.","redFlags":"Stridor, silent chest, profound hypoxia.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-076","category":"Clinical Skills","title":"Neurologic localization","pattern":"Pattern of weakness, sensory loss, reflex change and cranial findings helps localize lesions.","assessment":"Distinguish upper/lower motor neuron signs, symmetry, time course and cranial nerve deficits.","approach":"Call urgent stroke or spinal compression pathway if indicated.","pitfall":"Do not misinterpret poor effort as functional disorder without assessment.","redFlags":"Sudden deficit, rapidly progressive weakness, bowel/bladder change.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-077","category":"Clinical Skills","title":"Abdominal examination","pattern":"Inspection, percussion, palpation and focused maneuvers supplement a symptom history.","assessment":"Look for distension, scars, hernias, peritoneal signs and organ enlargement when appropriate.","approach":"Protect privacy, comfort and consent; refer acute abdomen early.","pitfall":"A soft abdomen can still accompany significant intra-abdominal illness.","redFlags":"Peritonitis, shock, pulsatile mass with pain.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-078","category":"Clinical Skills","title":"Musculoskeletal examination","pattern":"Look-feel-move approach documents joint function, inflammation and neurovascular status.","assessment":"Examine joints above and below injured site; compare sides and assess distal pulses/nerves.","approach":"Use safe handling and imaging when indicated; immobilization practices require training.","pitfall":"Pain-limited range is nonspecific and should not obscure neurovascular compromise.","redFlags":"Compartment syndrome concern, threatened limb circulation.","sources":["physical"],"level":"Clinical skills"},{"id":"sp-079","category":"Clinical Skills","title":"Medication reconciliation","pattern":"Discrepant medicine lists commonly occur at admission, transfer and discharge.","assessment":"Check name, indication, formulation, current use, OTC, supplements, allergies and renal function.","approach":"Resolve changes with prescriber/pharmacist; document verified sources.","pitfall":"Do not infer actual adherence from a printed prescription list.","redFlags":"Omitted insulin, anticoagulants, antiseizure drugs or critical chronic steroids.","sources":["who"],"level":"Clinical skills"},{"id":"sp-080","category":"Clinical Skills","title":"ECG systematic read","pattern":"Rate, rhythm, axis, intervals, QRS morphology, ST-T changes and prior comparison form a reproducible sequence.","assessment":"Check lead placement, artifacts and symptoms before diagnosis.","approach":"Escalate ischemia or unstable arrhythmia rather than seeking perfect pattern recognition.","pitfall":"A normal initial ECG does not exclude evolving ACS.","redFlags":"ST elevation with symptoms, broad-complex instability, high-grade heart block.","sources":["acs"],"level":"Clinical skills"},{"id":"sp-081","category":"Clinical Skills","title":"Chest radiograph approach","pattern":"Check patient, projection, inspiration, penetration and rotation before reviewing pathology.","assessment":"Use airway, lungs, pleura, heart, mediastinum, bones and devices in structured order.","approach":"Correlate with clinical state; comparison imaging improves confidence.","pitfall":"Portable AP projection can make heart appear enlarged.","redFlags":"Tension pneumothorax features, misplaced airway or chest device.","sources":["msd"],"level":"Clinical skills"},{"id":"sp-082","category":"Clinical Skills","title":"ABG systematic read","pattern":"Check sample and oxygen support; interpret pH, PaCO2, bicarbonate and lactate with context.","assessment":"Assess primary process, expected compensation, anion gap and mixed disorders.","approach":"Trend clinical condition and obtain urgent review of severe abnormalities.","pitfall":"Near-normal pH may hide two opposing disturbances.","redFlags":"Profound acidosis with circulatory or respiratory failure.","sources":["lab"],"level":"Clinical skills"}],"tests":[{"id":"dx-001","title":"ECG — atrial fibrillation","focus":"An irregularly irregular ventricular rhythm with no consistent discrete P waves suggests AF; consider artifacts.","pitfall":"No single rhythm strip determines anticoagulation eligibility.","source":"acs"},{"id":"dx-002","title":"ECG — high-grade AV block","focus":"Look for relationship between P waves and QRS complexes, escape rate and perfusion status.","pitfall":"Not all bradycardia is benign; symptoms and hemodynamics matter.","source":"aha"},{"id":"dx-003","title":"ECG — hyperkalemia","focus":"Changes can include peaked T waves, PR prolongation and QRS widening, but no ECG change reliably excludes severe potassium excess.","pitfall":"Never use ECG alone to clear a critical potassium level.","source":"aki"},{"id":"dx-004","title":"ECG — narrow-complex tachycardia","focus":"Assess QRS width, regularity, hemodynamics and 12-lead findings; multiple supraventricular mechanisms possible.","pitfall":"Avoid inferring mechanism solely from heart rate.","source":"msd"},{"id":"dx-005","title":"ECG — broad-complex tachycardia","focus":"Treat as potentially ventricular until appropriately assessed; correlate pulse and clinical stability.","pitfall":"Misclassification can create dangerous management errors.","source":"aha"},{"id":"dx-006","title":"ECG — acute ischemia","focus":"Look for regional ST-T changes, reciprocal features and serial evolution in the right clinical context.","pitfall":"False reassurance from a single apparently normal ECG is dangerous.","source":"acs"},{"id":"dx-007","title":"Cardiac troponin","focus":"Dynamic rise/fall and clinical evidence determine type and cause of myocardial injury.","pitfall":"Elevated troponin is not synonymous with type 1 myocardial infarction.","source":"acs"},{"id":"dx-008","title":"NT-proBNP / BNP","focus":"Natriuretic peptides reflect myocardial wall stress and can support a heart-failure workup.","pitfall":"Interpret with age, obesity, renal function and clinical setting.","source":"msd"},{"id":"dx-009","title":"D-dimer","focus":"A sensitive but nonspecific fibrin degradation marker for selected patients with low/intermediate pretest likelihood.","pitfall":"Do not use to rule out VTE when clinical probability is high.","source":"vte"},{"id":"dx-010","title":"CBC — microcytosis","focus":"Review hemoglobin, MCV, reticulocytes, ferritin and clinical bleeding risk.","pitfall":"Ferritin may be falsely reassuring in inflammation.","source":"lab"},{"id":"dx-011","title":"CBC — macrocytosis","focus":"Consider vitamin deficiencies, reticulocytosis, liver disease, thyroid dysfunction and marrow causes.","pitfall":"Normal hemoglobin does not exclude early deficiency.","source":"lab"},{"id":"dx-012","title":"CBC — leukocytosis","focus":"Interpret differential and trend with stress, medications, inflammation, malignancy and infection.","pitfall":"An elevated count by itself proves neither bacterial infection nor sepsis.","source":"lab"},{"id":"dx-013","title":"Platelet count","focus":"Verify unexpected values and examine morphology when relevant.","pitfall":"Pseudothrombocytopenia from EDTA clumping can mislead.","source":"lab"},{"id":"dx-014","title":"Reticulocyte count","focus":"Helps distinguish low marrow response from increased red cell turnover or blood loss.","pitfall":"Interpret alongside hemoglobin and time since event.","source":"lab"},{"id":"dx-015","title":"Peripheral blood film","focus":"Morphology may reveal schistocytes, blasts, hemolytic features or hemoglobinopathy clues.","pitfall":"Interpret with the clinical laboratory and specialist help.","source":"lab"},{"id":"dx-016","title":"Creatinine and eGFR","focus":"Estimate filtration while considering muscle mass and whether kidney function is stable.","pitfall":"eGFR equations may be misleading in evolving AKI.","source":"ckd"},{"id":"dx-017","title":"Urine albumin/creatinine ratio","focus":"Detects albuminuria and contributes to CKD risk staging.","pitfall":"Transient illness or exercise may affect results; repeat when indicated.","source":"ckd"},{"id":"dx-018","title":"Urinalysis microscopy","focus":"Blood, leukocytes, casts, protein and contaminants inform renal and urinary differential diagnosis.","pitfall":"Dipstick positivity alone does not identify a pathogen.","source":"aki"},{"id":"dx-019","title":"Liver function pattern","focus":"ALT/AST, ALP/GGT, bilirubin, albumin and INR reflect distinct liver and nonliver processes.","pitfall":"Albumin and INR have nonhepatic influences; isolated high ALP may reflect bone.","source":"msd"},{"id":"dx-020","title":"Coagulation profile","focus":"PT/INR and APTT are assay-based clues to anticoagulant effect, liver disease and coagulation pathways.","pitfall":"Normal standard tests do not exclude all bleeding disorders.","source":"lab"},{"id":"dx-021","title":"Thyroid testing","focus":"TSH and free T4 are interpreted together with pituitary status, pregnancy and illness.","pitfall":"Biotin and nonthyroidal illness can distort thyroid assays.","source":"msd"},{"id":"dx-022","title":"HbA1c","focus":"Approximates recent glycemic exposure, but red-cell turnover and hemoglobin variants can alter reliability.","pitfall":"Use direct glucose measures when HbA1c is unreliable.","source":"diabetes"},{"id":"dx-023","title":"Blood gas","focus":"Interpret sample type, oxygen therapy, pH, CO2, bicarbonate and lactate together.","pitfall":"Venous PO2 cannot replace arterial oxygenation assessment.","source":"lab"},{"id":"dx-024","title":"Lactate","focus":"May rise in hypoperfusion, catecholamine exposure, seizures, liver disease and other conditions.","pitfall":"A normal lactate does not rule out serious sepsis or shock.","source":"ssc"},{"id":"dx-025","title":"Blood cultures","focus":"Collect when indicated with aseptic technique and appropriate volume before antibiotics when safe and without delaying lifesaving therapy.","pitfall":"Contamination and insufficient volume decrease utility.","source":"steward"},{"id":"dx-026","title":"Chest X-ray","focus":"Assess quality, consolidation, pleura, edema, hyperinflation and lines/tubes.","pitfall":"A normal or subtle image does not exclude early important pathology.","source":"msd"},{"id":"dx-027","title":"Bedside lung ultrasound","focus":"Pleural fluid, pneumothorax signs and B-lines offer useful context in trained hands.","pitfall":"Operator-dependent and must not override deterioration.","source":"physical"},{"id":"dx-028","title":"CT brain","focus":"Used in selected neurologic emergencies to characterize hemorrhage, mass effect and other findings.","pitfall":"Early CT may be nondiagnostic for some ischemic strokes.","source":"neuro"},{"id":"dx-029","title":"MRI brain","focus":"Different sequences reveal diffusion restriction, inflammation, tumors and demyelination.","pitfall":"MRI contraindications and availability affect decision-making.","source":"neuro"},{"id":"dx-030","title":"Pulmonary function tests","focus":"Spirometry measures airflow patterns; interpret with acceptability and repeatability criteria.","pitfall":"Poor effort can mimic obstruction or restriction.","source":"copd"},{"id":"dx-031","title":"Echocardiogram","focus":"Assesses ventricular function, valves, chambers and regional wall motion.","pitfall":"Normal EF does not rule out HFpEF or all cardiac disease.","source":"msd"},{"id":"dx-032","title":"Blood glucose/ketones","focus":"Point-of-care glucose and capillary or serum ketones can support metabolic emergency recognition.","pitfall":"Euglycemic DKA can occur.","source":"diabetes"},{"id":"dx-033","title":"Pregnancy testing","focus":"Pregnancy status changes differential diagnosis, imaging and medication risk.","pitfall":"Early pregnancy may produce initially negative tests; use clinical follow-up.","source":"ob"},{"id":"dx-034","title":"Urine culture","focus":"Consider symptomatic infection likelihood and contamination; colony counts require interpretation.","pitfall":"Asymptomatic bacteriuria usually does not require treatment outside special scenarios.","source":"steward"}],"skills":[{"id":"osce-001","title":"Focused history","steps":["Confirm identifiers and consent","Establish onset, tempo and associated features","Ask medicines, allergies, history, occupation and family context","Explore patient ideas, concerns, expectations","Summarize and safety-net"],"source":"who"},{"id":"osce-002","title":"Cardiovascular exam","steps":["Hand hygiene, consent and appropriate exposure","Observe pulse rate/rhythm, blood pressure and peripheral signs","Assess JVP and palpate apex if appropriate","Auscultate valves with maneuvers when appropriate","Explain findings and follow-up investigations"],"source":"physical"},{"id":"osce-003","title":"Respiratory exam","steps":["Hand hygiene, consent and respiratory safety check","Check work of breathing and breathing rate","Compare chest expansion, percussion and air entry","Auscultate symmetrically, noting added sounds","Summarize respiratory status and escalate any compromise"],"source":"physical"},{"id":"osce-004","title":"Abdominal exam","steps":["Ensure consent, privacy and comfort","Inspect distension, scars and movement","Auscultate and percuss as locally taught","Palpate gently, leaving painful area until last","Explain differential and further investigations"],"source":"physical"},{"id":"osce-005","title":"Neurological screening","steps":["Establish baseline and full symptom time course","Assess mental state, speech and pupils as relevant","Compare strength, tone, sensation and reflexes","Test gait and coordination if safe","Document localization, asymmetry and any urgent deficit"],"source":"physical"},{"id":"osce-006","title":"Cranial nerve exam","steps":["Explain the purpose and obtain consent","Observe eye movements, pupils and visual fields where appropriate","Assess face, hearing, palate, tongue and shoulder function","Compare sides and distinguish central versus peripheral patterns","State localization and limitations"],"source":"physical"},{"id":"osce-007","title":"Diabetes review","steps":["Check type, duration and glycemic monitoring","Review hypo episodes, medication and injection technique","Assess kidney, eye, foot, cardiovascular risks","Discuss nutrition and personal treatment goals","Document follow-up and sick-day education needs"],"source":"who"},{"id":"osce-008","title":"Medication history","steps":["Ask what is really being taken","Include prescription, OTC, herbal and supplements","Clarify allergy versus side effect and exact reaction","Check timing, adherence, changes, devices, pharmacies","Reconcile with records and escalate discrepancies"],"source":"who"},{"id":"osce-009","title":"Sepsis handover","steps":["Identify time course and suspected infectious source","Share physiological trend and clinical red flags","Report relevant lactate, cultures and organ abnormalities","State senior review and urgent pending tasks","Confirm receiver understands and accepts actions"],"source":"who"},{"id":"osce-010","title":"Preoperative assessment","steps":["Confirm identity, indication and consent pathway","Check medical/anaesthetic history and allergies","Review medicine, anticoagulation and comorbidities","Assess baseline function and airway concerns","Use approved checklist and local protocol"],"source":"who"},{"id":"osce-011","title":"Discharge summary","steps":["Explain diagnosis and uncertainty","List medication changes with indication and duration","State follow-up tests and who owns them","Safety-net symptoms that warrant return","Use plain-language teach-back"],"source":"who"},{"id":"osce-012","title":"Shared decision-making","steps":["Establish patient goals and understanding","Explain reasonable alternatives and uncertainty","Discuss benefits, risks, and what not treating may mean","Check comprehension and voluntariness","Document agreed plan and follow-up"],"source":"who"},{"id":"osce-013","title":"Interpreting an ECG","steps":["Identify patient, date, trace quality","Review rate, rhythm, axis, intervals, QRS","Inspect ST and T changes with clinical context","Compare prior ECG where available","State urgency and need for senior confirmation"],"source":"physical"},{"id":"osce-014","title":"Interpreting a CXR","steps":["Confirm image name, time and projection","Assess rotation, inspiration, penetration","Review airway, bones, cardiac silhouette, diaphragms","Inspect lungs, pleura and lines or tubes","Use clinical context and report uncertainty"],"source":"physical"},{"id":"osce-015","title":"Neurological observations","steps":["Establish baseline GCS or AVPU","Assess pupils, motor signs and vital trends","Note triggers, medication and sedation","Recognize new asymmetry or reduced arousal","Escalate deterioration and document times"],"source":"who"},{"id":"osce-016","title":"Handover with SBAR","steps":["State patient and immediate situation","Give concise background and objective findings","Present assessment with uncertainty","Make explicit recommendation and urgency","Request read-back of critical information"],"source":"who"},{"id":"osce-017","title":"Culture and isolation","steps":["Use universal standard precautions","Choose additional measures based on likely transmission","Handle specimens with appropriate packaging","Clean devices and spaces per local protocols","Report occupational exposure immediately"],"source":"who"},{"id":"osce-018","title":"Peripheral edema assessment","steps":["Examine symmetry and onset","Assess cardiopulmonary, renal and hepatic symptoms","Check medicines and VTE risk","Review exam and relevant investigations","Escalate unilateral painful swelling or breathlessness"],"source":"who"},{"id":"osce-019","title":"Falls assessment","steps":["Clarify event and any loss of consciousness","Check injury, orthostatic symptoms and ECG risk","Assess gait, vision, medication and environment","Discuss practical prevention and support","Escalate suspected head bleed or new neurologic deficit"],"source":"who"},{"id":"osce-020","title":"Acute pain assessment","steps":["Establish location, onset, character and severity","Explore red flags and associated features","Check analgesia already taken and its response","Avoid diagnostic anchoring on pain intensity","Reassess after treatment and plan follow-up"],"source":"who"}],"references":[{"id":"openstax","title":"OpenStax Anatomy & Physiology 2e","url":"https://openstax.org/subjects/anatomy-and-physiology","edition":"CC BY 4.0 textbook","scope":"Foundational anatomy and physiology"},{"id":"physical","title":"Stanford Medicine 25 — Bedside Examination","url":"https://stanfordmedicine25.stanford.edu/the25.html","edition":"Educational teaching collection","scope":"Bedside examination techniques"},{"id":"msd","title":"MSD Manuals — Professional","url":"https://www.msdmanuals.com/professional","edition":"Clinical reference hub","scope":"Clinical background, not a protocol"},{"id":"medline","title":"MedlinePlus — Medical Tests","url":"https://medlineplus.gov/lab-tests/","edition":"NIH patient education","scope":"Interpretation must use local laboratory intervals"},{"id":"sepsis","title":"NICE NG253 — Suspected Sepsis in Adults","url":"https://www.nice.org.uk/guidance/ng253","edition":"Updated September 2026","scope":"Excludes pregnancy and patients under age 16"},{"id":"ssc","title":"Surviving Sepsis Campaign 2026","url":"https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026","edition":"March 2026","scope":"Critical-care guidance; institution adaptation required"},{"id":"acs","title":"NICE NG185 — Acute Coronary Syndromes","url":"https://www.nice.org.uk/guidance/ng185","edition":"2020; reviewed March 2026","scope":"ACS including STEMI/NSTEMI"},{"id":"vte","title":"NICE NG158 — Venous Thromboembolism","url":"https://www.nice.org.uk/guidance/ng158","edition":"2023; reviewed May 2026","scope":"Does not cover pregnancy"},{"id":"ckd","title":"KDIGO 2024 CKD Guideline","url":"https://kdigo.org/guidelines/ckd-evaluation-and-management/","edition":"2024","scope":"CKD classification and risk"},{"id":"aki","title":"NICE NG148 — Acute Kidney Injury","url":"https://www.nice.org.uk/guidance/ng148","edition":"Current guideline page","scope":"AKI recognition and investigation"},{"id":"asthma","title":"GINA 2026 — Global Strategy for Asthma","url":"https://ginasthma.org/2026-gina-strategy-report/","edition":"2026","scope":"External copyrighted guide, link only"},{"id":"copd","title":"GOLD 2026 — COPD Report","url":"https://goldcopd.org/2026-gold-report-and-pocket-guide/","edition":"2026","scope":"External copyrighted strategy, link only"},{"id":"diabetes","title":"NICE NG28 — Type 2 Diabetes in Adults","url":"https://www.nice.org.uk/guidance/ng28","edition":"Updated February 2026","scope":"Adult treatment individualized"},{"id":"hypertension","title":"NICE NG136 — Hypertension in Adults","url":"https://www.nice.org.uk/guidance/ng136","edition":"Updated February 2026","scope":"Consider ABPM or HBPM"},{"id":"cancer","title":"NICE NG12 — Suspected Cancer Referral","url":"https://www.nice.org.uk/guidance/ng12","edition":"Updated April 2026","scope":"Referral depends on age, symptoms, and jurisdiction"},{"id":"aha","title":"AHA 2025 CPR & ECC Guidelines","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines","edition":"2025","scope":"Formal accredited practical training required"},{"id":"cdc","title":"CDC — Core Infection Prevention Practices","url":"https://www.cdc.gov/infection-control/hcp/core-practices/","edition":"2024","scope":"Healthcare setting-specific precautions"},{"id":"tb","title":"WHO 2025 — Tuberculosis Diagnosis","url":"https://www.who.int/publications/i/item/9789240107984","edition":"2025","scope":"National TB program protocols apply"},{"id":"tbcare","title":"WHO 2025 — Tuberculosis Treatment & Care","url":"https://www.who.int/publications/i/item/9789240107243","edition":"2025","scope":"National program protocols apply"},{"id":"steward","title":"NICE NG15 — Antimicrobial Stewardship","url":"https://www.nice.org.uk/guidance/ng15","edition":"Current guideline page","scope":"Local antibiogram and prescribing rules take precedence"},{"id":"vacc","title":"CDC — Adult Immunization Schedule","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-age.html","edition":"Schedule subject to legal and policy change","scope":"Verify in local region"},{"id":"neuro","title":"NICE NG128 — Stroke and TIA","url":"https://www.nice.org.uk/guidance/ng128","edition":"Current guideline page","scope":"Time-sensitive specialist assessment"},{"id":"meningitis","title":"NICE NG240 — Bacterial Meningitis & Meningococcal Disease","url":"https://www.nice.org.uk/guidance/ng240","edition":"Current guideline page","scope":"Emergency presentation"},{"id":"ob","title":"WHO — Maternal Health","url":"https://www.who.int/health-topics/maternal-health","edition":"WHO topic hub","scope":"Obstetric protocols must be locally verified"},{"id":"pediatric","title":"WHO — Child Health","url":"https://www.who.int/health-topics/child-health","edition":"WHO topic hub","scope":"Age and weight significantly affect assessment"},{"id":"epilepsy","title":"NICE NG217 — Epilepsies","url":"https://www.nice.org.uk/guidance/ng217","edition":"Current guideline page","scope":"Seizure type drives differential"},{"id":"ethics","title":"GMC — Good Medical Practice","url":"https://www.gmc-uk.org/professional-standards/professional-standards-for-doctors/good-medical-practice","edition":"2024 standards","scope":"Local law, registration rules vary"},{"id":"who","title":"WHO — Patient Safety","url":"https://www.who.int/health-topics/patient-safety","edition":"WHO topic hub","scope":"Safety systems and escalation"},{"id":"lab","title":"MedlinePlus — Laboratory Tests","url":"https://medlineplus.gov/lab-tests/","edition":"NIH educational pages","scope":"Follow laboratory and patient-specific interpretation"}],"disclaimer":"Educational revision notes, not peer-reviewed or approved clinical protocols. Reference links provide further reading and do not verify every sentence; check guidance date, contraindications, local policies, and prescribing labels."};